  '## Slide 3\nWorking with Strings\nstringr package (in tidyverse)\n\nwww.gastonsanchez.com/Handling_and_Processing_Strings_in_R.pdf\n![Image placeholder for 1 image(s) on slide 3]',
  '## Slide 4\nReading in Character Strings from Files\nread_file() reads in the entire file as a single character string\nread_lines() creates a vector of character strings, each one from the \n	file is a separate line',
  '## Slide 5\nChanging the Case\nstr_to_lower(x),str_to_upper(x), str_to_title(x) and str_to_sentence(x)\nExamples:\n	str_to_lower(“Villanova”)\n	str_to_upper(state.name)\n![Image placeholder for 2 image(s) on slide 5]',
  '## Slide 6\nstr_sub (stringr) or substr (base)\nstr_sub(string,start,end)\n	note: negative numbers count from the end\nstr_sub("Villanova",1,1) 		# extracts the first value\nstr_sub("Villanova",6,9) 		# extracts our nickname\nstr_sub("Villanova",6)		# another version (6 to end)\nstr_sub("Villanova",-4)		# another version (4th from end)\nstr_sub(state.name,1,3)\nAnother option:\n	abbreviate(state.name)\nSubstrings\n![Image placeholder for 4 image(s) on slide 6]',
  '## Slide 7\nFind Character Strings\nstr_which(vector, pattern)  [base::grep] identifies the indices of matches\nstr_which(c(“Aardvark”,”Anteater”,”Alligator”),”k”)   =>   1\nstr_subset() identifies the values of matches [base::grep(value=T)]\nstr_subset(c(“Aardvark”,”Anteater”,”Alligator”),”k”)   =>   “Aardvark”\nstr_detect() produces logical vector instead of count [base::grepl]\nUseful for using with mutate or other functions that require vectors\nstr_detect(c(“Aardvark”,”Anteater”,”Alligator”),”k”)   =>   T  F  F\nSeries of characters\nYou can use “[]” to identify series of characters\nYou can use “-” within “[]” to identify related characters\nstr_detect(c(“Aardvark”,”Anteater”,”Alligator”),”[gk]”)   =>   T  F  T',
  '## Slide 8\nFind Character Strings II\nstr_which(state.name,”V”)  # lists all states with a V in it\n			# actually, it lists the index\nstr_subset(state.name,”V”)\n			# Hey, what happened to Pennsylvania?\nstr_subset(str_to_upper(state.name),”V”)\n\nstr_subset(state.name,”[Vv]”)  # searches for “V” or “v”\n![Image placeholder for 4 image(s) on slide 8]',
  '## Slide 9\nFind and Replace\nstr_replace(string, pattern, replacement)  # replaces first occurrence\nstr_replace_all(string, pattern, replacement)  # replaces all occurrences\nTo remove spaces from state names,\n	states_nospace <- str_replace_all(state.name, “ “, “”)\n\n\n\n\nBetter yet, you can use str_remove_all(state.name,” “) instead…\n![Image placeholder for 1 image(s) on slide 9]',
  '## Slide 10\nCounting String Occurrence\nstr_count(string,pattern)\nstr_count(“pneumonoultramicroscopicsilicovolcanoconiosis”,”[aeiou]”)\nfruit <- c("apple", "banana", "pear", "pineapple")\nstr_count(fruit, "a")\nhas_ss <- str_count(str_to_lower(state.name),"ss")   # what is this asking for?\nstate.name[has_ss>0]\nstate.name[has_ss>1]\nstr_count(read_file("https://en.wikipedia.org/wiki/Villanova_University"),"Villanova")\n	The word “Villanova” appears 613 times\n![Image placeholder for 4 image(s) on slide 10]',
  '## Slide 11\nPaste (Concatenate)\npaste("Pi is ",pi)\npaste("Pi is about",round(pi,5))\npaste("Pi=",pi)\npaste("Pi=",pi,sep="")\npaste0("Pi=",pi)  # shortcut for paste with sep=“”\n\n# For different length vectors, you can combine values\npaste("MAT",1:5,sep="-")\n![Image placeholder for 2 image(s) on slide 11]',
  '## Slide 12\nUsing Paste in Titles\nlabs(subtitle=paste("Correlation=",\n	round(cor(badinc$avginc,badinc$badavginc),4)))\n![Image placeholder for 1 image(s) on slide 12]',
  '## Slide 13\nMeta-characters\nstring <- c("$20.00", "$40")\nstr_remove_all(string,"$")\n	“$20.00”     “$40”\nstr_remove_all(string,“\\$")\n	“20.00”     “40”\n![Image placeholder for 1 image(s) on slide 13]',
  '## Slide 14\nCharacter Classes\nRegular expressions (regex)\nAre patterns describing text\n^ is a negating qualifier\n![Image placeholder for 1 image(s) on slide 14]',
  '## Slide 15\nAnchor Sequences\nExamples:\nstr_replace_all("the dandelion war of 	2010“, "\\d", "_")\n     “the dandelion war of ____”\nmyword <- “t e s t i f y”\nprint(“Let’s play hangman…”)\nstr_replace_all(myword,”\\w”,”_”)\n	Let’s play hangman…\n	_ _ _ _ _ _ _\n(person guesses “t”)\nstr_replace_all(myword,"[^t\\s]","_")\n	t _ _ t _ _ _ \n(person guesses “e”)\nstr_replace_all(myword,"[^te\\s]","_")\n	t e _ t _ _ _\n![Image placeholder for 1 image(s) on slide 15]',
  '## Slide 16\nQuantifiers\nstr_subset(state.name,”e”)\n		Connecticut  Delaware  Georgia, etc.\nstr_subset(state.name,”e{2,}”)   # Looks for 2 e’s in a row…\n		Tennessee\n![Image placeholder for 1 image(s) on slide 16]',
  '## Slide 17\nYour Turn\nChoose five people’s names and enter them into a vector\nExtract the first three characters of each name\nCombine the first and last letter of name into a character string (of length 2)\nCreate two variables\ni)    the number of vowels in each person’s name\nii)   the proportion of vowels in each person’s name\nGraph these variables by name\nChoose any website and identify the number of times a specific word appears on it [Note – you likely want to save the file as text first]\nUse the babynames dataset to…\nplot n over time by name for girls whose name starts with “Elizab” but isn’t “Elizabeth”\nHow many unique names are there that contain the string “liz”\nExplore derivations of your own name',
  '## Slide 18\nYour Turn Solutions\n# a\nsmithposners <- c("Michael","Wendy","Yael","Jonah","Ari")\n# b\nstr_sub(smithposners,1,3)\n#c\npaste0(str_sub(smithposners,1,1),str_sub(smithposners,-1))\n# d\nspv0 <- str_count(smithposners,"[aeiou]")\nspv <- str_count(str_to_lower(smithposners),"[aeiou]")\nspv[spv==0] <- str_count(str_to_lower(smithposners),"y")\nsps <- data.frame(names=smithposners, spv)\nggplot(sps) + geom_col(aes(reorder(names,desc(spv)),spv), fill=“blue”)\nsps <- mutate(sps, spvp = spv / str_length(names))\nggplot(sps) + geom_col(aes(reorder(names,desc(spvp)),spvp), fill=“blue”)\n![Image placeholder for 4 image(s) on slide 18]',
  '## Slide 19\nYour Turn Solutions\n![Image placeholder for 2 image(s) on slide 19]',
