  '## Slide 21\nYour Turn Solutions\n# f ii)\nbabynames %>%  \n  filter(str_detect(name,"liz")) %>% \n  count(name) %>% \n  nrow()\nbabynames %>% \n  filter(str_detect(str_to_lower(name),"liz")) %>% \n  count(name) %>% \n  nrow()\n![Image placeholder for 2 image(s) on slide 21]',
  '## Slide 22\nYour Turn - Solutions\n# f iii)\nbabynames %>%\n   mutate(michael_type = case_when(\n	name=="Michael" & sex=="M" ~ "Michael_M",    \n	name=="Michael" ~ "Michael_F",    \n	str_sub(name,1,7) == "Michael" ~ "Michael_Other")) %>%  \n   group_by(year, michael_type, sex) %>%   \n	summarize(total = sum(n), \n		.groups = "drop") %>%\n    drop_na(michael_type)\n![Image placeholder for 1 image(s) on slide 22]',
  '## Slide 23\nYour Turn - Solutions\n# f iii) geom_line(aes(x=year,y=total,lty=sex,color=michael_type))\n	+  scale_y_log10(breaks = 10^(1:5), labels = paste0("10^",1:5))\n![Image placeholder for 2 image(s) on slide 23]',
