  '## Slide 26\nTokenization (Parsing the File by Word)\nmission %>% str_split(" ")  # split on each space\n\n\n\n\nmission %>% str_split("\\s+") # split on 1+ space, incl \n and \r\n![Image placeholder for 2 image(s) on slide 26]',
  '## Slide 27\nTokenization II\nmission %>% str_split("\\s+") %>% .[[1]]    # first item in list\nmission %>% str_split("\\s+") %>% unlist()   # unlists in data.frame\n\n\n\nmission %>% str_remove_all("[[:punct:]]") %>% \n	str_split("\\s+") %>% unlist() %>% 	str_to_lower()\n![Image placeholder for 2 image(s) on slide 27]',
  '## Slide 28\nTokenization III\nmissionwords <- mission %>% \n	str_remove_all("[[:punct:]]") %>% 	# remove punctuation* \n	str_split("\\s+") %>% 			# splits on spaces +\n	unlist() %>% 				# make into data.frame\n	str_to_lower() %>%			# makes lower case\n	data.frame(words=.)		 	# add this to make data.frame\n			* different result if you put this before unlist.  Why?\nmissionwords %>% nrow()\nmissionwords %>% n_distinct(words)\nTechnically, “tokenizing” then assigns each word to a number\n![Image placeholder for 2 image(s) on slide 28]',
