  '## Slide 32\nGraph of Mission Statement Words\nmissionwords %>% \n   filter(words %in% stopwords("english") == F) %>% \n   count(words) %>% \n   arrange(desc(n)) %>% \n   filter(n>=3) %>%\n   ggplot() +\n   geom_col(aes(words,n))\n![Image placeholder for 1 image(s) on slide 32]',
  '## Slide 33\nGraph of Mission Statement Words II\nmissionwords %>% \n   filter(words %in% stopwords("english") == F) %>% \n   count(words) %>% \n   arrange(desc(n)) %>% \n   filter(n>=3) %>%\n   ggplot() +\n   geom_col(aes(reorder(words,n),\n	n,fill=n)) +\n   coord_flip() +\n   labs(y="word", x="freq") + \n   guides(fill=F)\n![Image placeholder for 1 image(s) on slide 33]',
